                  source: "Advanced Race Guide", isPremium: true),

        ]

        for race in races {
            try await db.insertRace(race)
        }
    }
}

// MARK: - RaceEntry factory
private extension RaceEntry {
    static func make(
        _ title: String,
        size: String,
        speed: String,
        abilityModifiers: String,
        racialTraits: [String],
        languages: [String],
        summary: String,
        desc: String,
        source: String = "Core Rulebook",
        isPremium: Bool = false
    ) -> RaceEntry {
        RaceEntry(
            id: UUID(),
            title: title,
            summary: summary,
            isPremium: isPremium,
            size: size,
            speed: speed,
            abilityModifiers: abilityModifiers,
            racialTraits: racialTraits,
            languages: languages,
            description: desc,
            source: source
        )
    }
}